S.append(site("cave-spring", "ca", "Cave Spring Cellars", "estate", "Twenty Mile Bench", 43.1494, -79.3702, "Len Pennachetti and Angelo Pavan founded Cave Spring in 1986 in an 1870s apple warehouse in the village of Jordan; their Riesling and Chardonnay from Beamsville Bench and Twenty Mile Bench vineyards helped define bench terroir.", cls="Founded 1986", producers=["Cave Spring"]))
S.append(site("tawse", "ca", "Tawse Winery", "estate", "Twenty Mile Bench", 43.1515, -79.4117, "Moray Tawse's gravity-flow, organic and biodynamic winery near Vineland; it was named Canadian Winery of the Year several times and is known for Burgundian Chardonnay and Pinot Noir.", producers=["Tawse"]))
S.append(site("pelee-island-winery", "ca", "Pelee Island Winery", "estate", "South Islands", 42.0375, -82.7213, "Pelee Island Winery farms Canada's southernmost vineyards on Pelee Island, with its main winery at Kingsville on the mainland; it made Ontario's first successful icewine in 1983 (50 bottles).", producers=["Pelee Island Winery"]))
S.append(site("vin-villa", "ca", "Vin Villa ruins, Pelee Island", "historic", "South Islands", 41.795, -82.660, "Kentucky planters Thaddeus Smith and Edward and William McCormick founded Vin Villa in 1866, Canada's first commercial winery, on Lake Erie's Pelee Island. Only stone ruins remain.", cls="Founded 1866", q="approx"))
S.append(site("schiller-cooksville", "ca", "Johann Schiller's Credit River vineyard (Cooksville)", "historic", "Ontario", 43.583, -79.624, "Around 1811, Johann Schiller, a German-born former corporal, made wine here from wild and cultivated vines; he is remembered as the father of Canadian wine. The site later became Clair House Vineyards. Today it is suburban Mississauga.", cls="c. 1811", q="approx"))
S.append(site("norman-hardie", "ca", "Norman Hardie Winery", "estate", "Prince Edward County", 43.9551, -77.4457, "Sommelier-turned-winemaker Norman Hardie planted on Prince Edward County's shallow clay over limestone in 2003 and showed that the County could make taut, low-alcohol, Burgundian Pinot Noir and Chardonnay. His vines, like most in the County, are buried under soil every winter.", producers=["Norman Hardie"]))
S.append(site("closson-chase", "ca", "Closson Chase", "estate", "Prince Edward County", 43.9991, -77.3929, "A purple barn turned winery, founded in 1998 by a group including film-maker Deborah Paskus, among the first to plant Chardonnay and Pinot Noir in the County.", producers=["Closson Chase"]))
S.append(site("pandosy-mission", "ca", "Father Pandosy Mission", "historic", "Okanagan Valley", 49.861, -119.456, "Oblate missionary Charles Pandosy founded this mission in 1859 and planted the Okanagan's first vines for sacramental wine. Several original log buildings survive as a heritage site in Kelowna.", cls="Founded 1859", q="approx"))
S.append(site("mission-hill", "ca", "Mission Hill Family Estate", "estate", "Okanagan Valley", 49.8356, -119.5875, "Anthony von Mandl's hilltop winery above West Kelowna, rebuilt in 2002 with a 12-storey bell tower; its 1992 Chardonnay won a major award at the International Wine & Spirit Competition in London in 1994, a turning point for BC wine.", producers=["Mission Hill"]))
S.append(site("quails-gate", "ca", "Quails' Gate", "estate", "Okanagan Valley", 49.8427, -119.5664, "The Stewart family, among the Okanagan's pioneer farmers, planted grapes on the west shore of Okanagan Lake in the 1950s and 1960s and founded the winery in 1989; known for Pinot Noir, Chardonnay and Chasselas.", producers=["Quails' Gate"]))
S.append(site("nkmip", "ca", "Nk'Mip Cellars", "estate", "Okanagan Valley", 49.0384, -119.4335, "Opened in 2002 by the Osoyoos Indian Band in partnership with Vincor, Nk'Mip (pronounced 'in-ka-meep') is widely described as the first Indigenous-owned and operated winery in North America, in the desert near Osoyoos.", cls="Founded 2002", producers=["Nk'Mip Cellars"]))
S.append(site("burrowing-owl", "ca", "Burrowing Owl Estate (Black Sage Bench)", "estate", "Okanagan Valley", 49.1014, -119.5327, "Jim Wyse founded Burrowing Owl on the hot, sandy Black Sage Bench south of Oliver in 1997; its Merlots and Bordeaux blends helped define the south Okanagan style. Part of its proceeds supported the recovery of the endangered burrowing owl.", producers=["Burrowing Owl"]))
S.append(site("painted-rock", "ca", "Painted Rock Estate", "estate", "Skaha Bench", 49.4284, -119.5706, "John Skinner planted a former apricot orchard on Skaha Bench in 2004; his Red Icon and Syrah were key evidence for the Skaha Bench sub-GI.", producers=["Painted Rock"]))
S.append(site("blue-mountain", "ca", "Blue Mountain Vineyard and Cellars", "estate", "Okanagan Falls", 49.324, -119.540, "The Mavety family, growers since 1971, founded this winery in 1991; its traditional-method sparkling wines and Pinot Noir from estate vines anchor the Okanagan Falls sub-GI.", q="approx", producers=["Blue Mountain"]))
S.append(site("orpailleur", "ca", "Vignoble de l'Orpailleur", "estate", "Vin du Québec", 45.1099, -72.8594, "Founded at Dunham in 1982 by Hervé Durand, Charles-Henri de Coussergues and partners, one of Quebec's first commercial wineries; it showed that Seyval Blanc and hilled-up vines could survive Quebec winters, and houses a wine museum.", cls="Founded 1982", producers=["L'Orpailleur"]))
S.append(site("cotes-dardoise", "ca", "Domaine des Côtes d'Ardoise", "estate", "Vin du Québec", 45.1158, -72.8399, "Planted in 1980 by Christian Barthomeuf on slate slopes at Dunham, often cited as the first commercial vineyard of modern Quebec. Barthomeuf later invented ice cider.", cls="Planted 1980", q="approx", producers=["Domaine des Côtes d'Ardoise"]))
S.append(site("domaine-pinnacle", "ca", "Domaine Pinnacle", "estate", "Cidre de glace du Québec", 45.0274, -72.7757, "An orchard estate at Frelighsburg on the slopes of Pinnacle Mountain near the Vermont border, founded in 2000; its ice cider brought the Quebec invention to international markets.", q="approx", producers=["Domaine Pinnacle"]))
S.append(site("benjamin-bridge", "ca", "Benjamin Bridge", "house", "Tidal Bay", 45.0604, -64.3821, "Gerry McConnell and Dara Gordon planted vines in the Gaspereau Valley in 2002 with consultant Peter J. Gamble and Champagne-trained advisers; its long-aged traditional-method sparkling wines and Nova 7 put Nova Scotia on the world map.", q="approx", producers=["Benjamin Bridge"]))
S.append(site("grand-pre", "ca", "Domaine de Grand Pré", "estate", "Tidal Bay", 45.1016, -64.3077, "Roger Dial opened Nova Scotia's first modern commercial winery here in 1979, beside the UNESCO-listed Acadian dykelands of Grand-Pré, reclaimed from the Bay of Fundy tides in the 1680s. Hanspeter Stutz bought it in 1993; it grows L'Acadie Blanc, Seyval and New York Muscat.", cls="Founded 1979", producers=["Domaine de Grand Pré"]))
